bounded_host_request.command:
set -u
docker exec -i debug-ai-debug-ai-1 node - >/dev/null 2>&1 <<'GACE_PROBE_JS'
(async () => {
  try {
    const {createAiCoreAdapter} = require('/app/server/adapters/ai-core.js');
    const e = process.env;
    const u = {coder:e.DEBUG_AI_CORE_GATE_CODER_URL, qwen3:e.DEBUG_AI_CORE_GATE_QWEN3_URL, granite:e.DEBUG_AI_CORE_GATE_GRANITE_URL, ministral:e.DEBUG_AI_CORE_GATE_MINISTRAL_URL};
    const a = createAiCoreAdapter({baseUrl:e.DEBUG_AI_CORE_URL,apiKey:e.AI_CORE_API_KEY,modelGateBaseUrls:u,dispatchMode:'model_gates'});
    await a.preflightConfiguredGates({probeTimeoutMs:2500});
    process.exit(0);
  } catch (err) {
    if (err.code === 'AI_CORE_GATE_HTTP') {
      process.exit(({401:31,429:32,503:33})[err.meta?.status] || 34);
    }
    const codes = {AI_CORE_GATE_MODEL_MISMATCH:41,AI_CORE_GATE_UNREACHABLE:40,AI_CORE_GATE_PREFLIGHT_TIMEOUT:43,AI_CORE_GATE_BODY_INVALID:44,AI_CORE_GATE_CONFIG_INVALID:45};
    process.exit(codes[err.code] || 49);
  }
})().catch(() => process.exit(70));
GACE_PROBE_JS
exit $?
